   321	function HomeScreen({ onEventPress, scrollPositionRef }) {
   322	  const [events, setEvents] = useState([]);
   323	  const [loading, setLoading] = useState(true);
   324	  const [loadingMore, setLoadingMore] = useState(false);
   325	  const [error, setError] = useState(null);
   326	  const [page, setPage] = useState(0);
   327	  const [timeFilter, setTimeFilter] = useState(null);
   328	  const [selectedCategories, setSelectedCategories] = useState([]);
   329	  const [selectedProvider, setSelectedProvider] = useState(null);
   330	  const [showProviderDropdown, setShowProviderDropdown] = useState(false);
   331	  const sectionListRef = useRef(null);
   332	  const scrollPositionRefLocal = useRef(0);
