   334	  const loadEvents = useCallback(async (pageNum = 0, isLoadMore = false) => {
   335	    if (isLoadMore) {
   336	      setLoadingMore(true);
   337	    } else {
   338	      setLoading(true);
   339	    }
   340	    
   341	    try {
   342	      const result = await fetchAllEventsViaServer();
   343	      const data = result.events || [];
   344	      
   345	      if (isLoadMore) {
   346	        setEvents(prev => [...prev, ...data]);
   347	      } else {
   348	        setEvents(data);
   349	      }
   350	      setPage(pageNum);
   351	    } catch (err) {
   352	      setError(err.message);
   353	      console.error('Failed to load events:', err);
   354	    } finally {
   355	      setLoading(false);
   356	      setLoadingMore(false);
   357	    }
   358	  }, []);
   359	
   360	  useEffect(() => {
   361	    loadEvents(0);
   362	  }, [loadEvents]);
   363	
   364	  const handleLoadMore = useCallback(() => {
   365	    // Only allow loading more when no filters are active
   366	    // This prevents API calls when user scrolls to end of filtered list
   367	    if (!loadingMore && !loading && !timeFilter && selectedCategories.length === 0) {
   368	      loadEvents(page + 1, true);
   369	    }
   370	  }, [loadingMore, loading, loadEvents, page, timeFilter, selectedCategories]);
   371	
   372	  const handleTimeFilterPress = useCallback((filterKey) => {
   373	    setTimeFilter(prev => prev === filterKey ? null : filterKey);
   374	  }, []);
   375	
   376	  const handleCategoryFilterPress = useCallback((categoryKey) => {
   377	    setSelectedCategories(prev => {
   378	      if (prev.includes(categoryKey)) {
   379	        return prev.filter(c => c !== categoryKey);
   380	      } else {
   381	        return [...prev, categoryKey];
   382	      }
   383	    });
   384	  }, []);
   385	
   386	  // Apply filters to events - memoized to prevent unnecessary recalculations
   387	  const filteredEvents = useMemo(() => {
   388	    let result = events;
   389	    
   390	    // First filter by category
   391	    if (selectedCategories.length > 0) {
   392	      result = result.filter(event => selectedCategories.includes(event.category));
   393	    }
   394	    
   395	    // Then filter by time
   396	    if (timeFilter) {
   397	      const now = new Date();
   398	      const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
   399	      
   400	      result = result.filter(event => {
   401	        if (!event.date) return false;
   402	        
   403	        const eventDate = new Date(event.date + 'T' + (event.time || '00:00'));
   404	        const eventDay = new Date(eventDate.getFullYear(), eventDate.getMonth(), eventDate.getDate());
   405	        
   406	        switch (timeFilter) {
   407	          case 'ikvall': {
   408	            const isToday = eventDay.getTime() === today.getTime();
   409	            return isToday && eventDate > now;
   410	          }
   411	          case 'imorgon': {
   412	            const tomorrow = new Date(today);
   413	            tomorrow.setDate(tomorrow.getDate() + 1);
   414	            return eventDay.getTime() === tomorrow.getTime();
   415	          }
   416	          case 'helgen': {
   417	            const dayOfWeek = eventDay.getDay();
   418	            return dayOfWeek === 0 || dayOfWeek === 6;
   419	          }
   420	          case 'denna_vecka': {
   421	            const nextWeek = new Date(today);
   422	            nextWeek.setDate(nextWeek.getDate() + 7);
   423	            return eventDay >= today && eventDay <= nextWeek;
   424	          }
   425	          default:
   426	            return true;
   427	        }
   428	      });
   429	    }
   430	    
   431	    // Finally filter by provider
   432	    if (selectedProvider) {
   433	      result = result.filter(event => event.source === selectedProvider);
   434	    }
   435	    
   436	    return result;
   437	  }, [events, timeFilter, selectedCategories, selectedProvider]);
